"""Render tables and figures from measurements generated by the experiments."""
import json
from pathlib import Path

import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np

LABELS = {'raw_pixels':'Raw pixels', 'random_vit':'Randomly initialized ViT-L/14',
          'openai':'Pretrained OpenAI CLIP ViT-L/14', 'random_gaussian':'i.i.d. Gaussian vectors'}


def write_table1(rows, output):
    output = Path(output)
    output.mkdir(parents=True,exist_ok=True)
    lines = ['| Representation | HAS-Viol (%) ↓ | HAS-Viol shuffled (%) ↓ |', '| --- | ---: | ---: |']
    latex = [r'\begin{tabular}{lcc}',r'\toprule',r'Representation & HAS-Viol (\%) & HAS-Viol shuffled (\%) \\',r'\midrule']
    for row in rows:
        # Match the manuscript: sample SD for random ViT; population SD otherwise.
        ddof = int(row['model']=='random_vit')
        def fmt(values):
            mean = np.mean(values)
            return f'{mean:.2f}' if len(values)==1 else f'{mean:.2f} ± {np.std(values,ddof=ddof):.2f}'
        observed, null = fmt(row['observed']), fmt(row['null'])
        label = LABELS[row['model']]
        lines.append(f'| {label} | {observed} | {null} |')
        latex.append(label+' & $'+observed.replace('±',r'\pm')+'$ & $'+null.replace('±',r'\pm')+r'$ \\')
    latex.extend([r'\bottomrule',r'\end{tabular}'])
    (output/'table1.md').write_text('\n'.join(lines)+'\n')
    (output/'table1.tex').write_text('\n'.join(latex)+'\n')


def plot_figure2(measurements, output):
    output = Path(output)
    output.mkdir(parents=True,exist_ok=True)
    titles = ['Randomly initialized','OpenAI CLIP','OpenCLIP (DataComp-1B)']
    fig, axes = plt.subplots(2,3,figsize=(13,7),layout='constrained')
    for row,modality in enumerate(['text','image']):
        for col,model in enumerate(['random_vit','openai','datacomp1b']):
            records = measurements[f'{modality}_{model}']['per_node_results']
            depths = sorted({r['depth'] for r in records})
            values = [[r['violation_proportion'] for r in records if r['depth']==d] for d in depths]
            ax=axes[row,col]
            ax.boxplot(values,positions=depths,showfliers=False)
            ax.set_xlabel('Hierarchy depth')
            ax.set_ylabel(f'{modality.capitalize()} HAS-Viol (%)')
            ax.set_ylim(-2,102)
            if row==0:
                ax.set_title(titles[col])
    for ext in ['png','pdf']:
        fig.savefig(output/f'figure2.{ext}',dpi=180)
    plt.close(fig)


def plot_figure5(measurements, output):
    from synthetic.plot_loss_violation import _apply_style, _plot_lambda_trace
    from synthetic.plot_noncentered_root import _plot_shift
    output = Path(output)
    output.mkdir(parents=True,exist_ok=True)
    _apply_style()
    trace = json.loads((measurements/'figure5_trace.json').read_text())['trace']
    _plot_lambda_trace(trace,output,'main_loss','figure5a','InfoNCE loss',0,10)
    raw = json.loads((measurements/'figure5_sweep.json').read_text())
    rows = [dict(shift=r['shift'],**{'lambda':r['lambda_reg']},hier_viol=r['hier_violation_mean'],
                 proto_align_min=r['prototype_align_min_nonroot']) for r in raw]
    _plot_shift(rows,1e-4,output,'proto_align_min','Prototype Alignment','protoalign')
